& \angle O \bar{A} C + \angle O \bar{B} C = \angle O \bar{A}^{\prime} C + \angle O \bar{B}^{\prime} C = 180^{\circ}
\end{aligned}
$$

Thus,

$$
\angle \overline{A A}^{\prime} \bar{A} = \angle O \bar{B} \bar{B}, \quad \angle O \bar{A} \bar{A}^{\prime} = \angle O \vec{B} \bar{B}^{\prime}
$$

